        {
          "md_line": 50,
          "block_header": "<!-- p -->",
          "author_transcribed_row": "$y'=\\frac{1}{x}\\cdot x^{-\\frac{p}{2}}+\\ln x\\left(-\\frac{p}{2}\\right)x^{-\\frac{p}{2}-1}=\\frac{p}{2x^{1+\\frac{p}{2}}}\\left(\\frac{2}{p}-\\ln x\\right)$，",
          "formula_printed_breaks": 0
