      "row_inventory": [
        {
          "md_line": 36,
          "block_header": "<!-- p cont -->",
          "author_transcribed_row": "的对数表. 纳白尔表和现今的自然对数表区别很小. 常用对",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 37,
          "block_header": "<!-- p cont -->",
          "author_transcribed_row": "数是由英国数学家布利格（1561—1617）引入的. 莱布尼兹早",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 38,
          "block_header": "<!-- p cont -->",
          "author_transcribed_row": "在十七世纪末就利用取对数的法则解指数方程. 利用对数表",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 39,
          "block_header": "<!-- p cont -->",
          "author_transcribed_row": "以及随后的对数尺大大地简化了计算，长久以来，它们就是一",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 40,
          "block_header": "<!-- p cont -->",
          "author_transcribed_row": "种主要的计算工具. 法国数学家拉普拉斯甚至说过，对数的",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 41,
          "block_header": "<!-- p cont -->",
          "author_transcribed_row": "发明延长了计算者的生命.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 44,
          "block_header": "<!-- exhead -->",
          "author_transcribed_row": "第八章补充题",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 47,
          "block_header": "<!-- exhead -->",
          "author_transcribed_row": "简略地画出函数的图象：",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 50,
          "block_header": "<!-- ex 724 -->",
          "author_transcribed_row": "724. $y=0.7^x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 53,
          "block_header": "<!-- ex 725 samerow -->",
          "author_transcribed_row": "725. $y=2.3^x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 56,
          "block_header": "<!-- ex 726 samerow -->",
          "author_transcribed_row": "726. $y=\\left(\\frac{1}{\\pi}\\right)^x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 59,
          "block_header": "<!-- ex 727 -->",
          "author_transcribed_row": "727. $y=3^{\\text{UNKNOWN}}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 62,
          "block_header": "<!-- ex 728 samerow -->",
          "author_transcribed_row": "728. $y=\\log_5 x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 65,
          "block_header": "<!-- ex 729 samerow -->",
          "author_transcribed_row": "729. $y=\\log_{0.6}x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 68,
          "block_header": "<!-- ex 730 -->",
          "author_transcribed_row": "730. $y=\\log_{1.7}x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 71,
          "block_header": "<!-- ex 731 samerow -->",
          "author_transcribed_row": "731. $y=\\log_{\\frac{1}{3}}x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 74,
          "block_header": "<!-- ex 732 samerow -->",
          "author_transcribed_row": "732. $y=|\\lg x|$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 77,
          "block_header": "<!-- ex 733 -->",
          "author_transcribed_row": "733. $y=\\lg|x|$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 80,
          "block_header": "<!-- ex 734 samerow -->",
          "author_transcribed_row": "734. $y=\\lg(-x)$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 83,
          "block_header": "<!-- ex 735 samerow -->",
          "author_transcribed_row": "735. *$y=\\lg(3-x)$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 86,
          "block_header": "<!-- ex 736 -->",
          "author_transcribed_row": "736. $y=\\lg(x-3)$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 89,
          "block_header": "<!-- ex 737 samerow -->",
          "author_transcribed_row": "737. $y=\\lg(x+3)$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 92,
          "block_header": "<!-- ex 738 samerow -->",
          "author_transcribed_row": "738. $y=\\lg x+3$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 95,
          "block_header": "<!-- ex 739 -->",
          "author_transcribed_row": "739. * $y=|\\log_2 x+1|$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 98,
          "block_header": "<!-- exhead -->",
          "author_transcribed_row": "求下列函数的导函数：",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 101,
          "block_header": "<!-- ex 740 -->",
          "author_transcribed_row": "740. $e^{3x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 104,
          "block_header": "<!-- ex 741 samerow -->",
          "author_transcribed_row": "741. $3e^{-2x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 107,
          "block_header": "<!-- ex 742 samerow -->",
          "author_transcribed_row": "742. $\\frac{7}{e^{5x}}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 110,
          "block_header": "<!-- ex 743 -->",
          "author_transcribed_row": "743. $\\left(\\frac{1}{e^{2x}}\\right)^3$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 113,
          "block_header": "<!-- ex 744 samerow -->",
          "author_transcribed_row": "744. $3^x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 116,
          "block_header": "<!-- ex 745 samerow -->",
          "author_transcribed_row": "745. $5^{-4x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 119,
          "block_header": "<!-- ex 746 -->",
          "author_transcribed_row": "746. $\\frac{3}{7^{2x}}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 122,
          "block_header": "<!-- ex 747 samerow -->",
          "author_transcribed_row": "747. $\\left(\\frac{5}{1.7^{3x}}\\right)^2$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 125,
          "block_header": "<!-- ex 748 samerow -->",
          "author_transcribed_row": "748. $9^{2-5x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 128,
          "block_header": "<!-- ex 749 -->",
          "author_transcribed_row": "749. $0.3^{7-2x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 131,
          "block_header": "<!-- ex 750 samerow -->",
          "author_transcribed_row": "750. $e^{\\sin x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 134,
          "block_header": "<!-- ex 751 samerow -->",
          "author_transcribed_row": "751. $e^{\\cos x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 137,
          "block_header": "<!-- ex 752 -->",
          "author_transcribed_row": "752. $3^{5\\operatorname{tg}x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 140,
          "block_header": "<!-- ex 753 samerow -->",
          "author_transcribed_row": "753. $7^{2\\operatorname{ctg}x}$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 143,
          "block_header": "<!-- ex 754 samerow -->",
          "author_transcribed_row": "754. *$5^x\\sin 2x$.",
          "formula_printed_breaks": 0
        },
        {
          "md_line": 146,
          "block_header": "<!-- foot -->",
